import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Integer> orders = List.of(300, 650, 900, 120);
        int bigTotal = orders.stream()
            .filter(o -> o > 500)
            .mapToInt(o -> o)
            .sum();
        System.out.println("Big orders total: " + bigTotal);

        List<String> names = List.of("ravi", "sita", "anu");
        List<String> shout = names.stream()
            .filter(n -> n.length() > 3)
            .map(n -> n.toUpperCase())
            .collect(Collectors.toList());
        System.out.println(shout);
        System.out.println(orders.stream().filter(o -> o < 500).count());
    }
}

