import java.util.List;

public class Main {
    static double averageOfPassed(List<Integer> marks) {
        return marks.stream()
            .filter(m -> m >= 35)
            .mapToInt(m -> m)
            .average()
            .orElse(0);
    }

    public static void main(String[] args) {
        System.out.println(averageOfPassed(List.of(20, 60, 80, 30)) + " " + averageOfPassed(List.of(10)));
    }
}

