import java.util.List;
import java.util.stream.Collectors;

record Candidate(String name, String branch, int score) { }

public class Main {
    static List<String> shortlist(List<Candidate> all, String branch, int minScore) {
        return all.stream()
            .filter(c -> c.branch().equals(branch) && c.score() >= minScore)
            .sorted((a, b) -> b.score() - a.score())
            .map(Candidate::name)
            .collect(Collectors.toList());
    }

    public static void main(String[] args) {
        List<Candidate> all = List.of(
            new Candidate("Ravi", "CSE", 78),
            new Candidate("Sita", "CSE", 91),
            new Candidate("Anu", "ECE", 88),
            new Candidate("Kiran", "CSE", 55));
        System.out.println(shortlist(all, "CSE", 60));
    }
}
